function printAdmissionReceipt(receipt:any){
 const escapeHtml=(value:any)=>String(value??"—").replace(/[&<>"']/g,ch=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[ch]));
 const rows=[['Receipt number',receipt.receiptNumber],['Payment date',receipt.paidAt?new Date(receipt.paidAt).toLocaleDateString():null],['Amount',`${receipt.currencyCode||"INR"} ${receipt.amount}`],['Payment method',receipt.paymentMethod],['Payment reference',receipt.paymentReference],['Status',receipt.status],['Application',receipt.applicationId],['Student',receipt.studentId]];
 const html=`<!doctype html><html><head><meta charset="utf-8"><title>Admission Receipt ${escapeHtml(receipt.receiptNumber)}</title><style>body{font-family:Arial,sans-serif;padding:32px;color:#111}h1{margin:0 0 8px}p{color:#555}table{border-collapse:collapse;width:100%;margin-top:24px}td{border-bottom:1px solid #ddd;padding:12px;text-align:left}td:first-child{font-weight:bold;width:38%}.footer{margin-top:28px;color:#555;font-size:12px}@media print{button{display:none}}</style></head><body><h1>Admission Payment Receipt</h1><p>Receipt for admission payment</p><table>${rows.map(([label,value])=>`<tr><td>${escapeHtml(label)}</td><td>${escapeHtml(value)}</td></tr>`).join('')}</table><p class="footer">This receipt records the payment captured in the school admission system.</p><button onclick="window.print()">Print</button></body></html>`;
 const win=window.open("","_blank","width=800,height=900");if(!win){alert("Please allow pop-ups to print this receipt.");return;}win.opener=null;win.document.open();win.document.write(html);win.document.close();
}
function buildAdmissionDecisionTimeline(stageHistory:any[], reviewNotes:any[]){
 const events:any[]=[];
 for(const h of stageHistory||[])events.push({key:`stage-${h.id}`,at:h.createdAt,type:"STAGE",title:`${h.fromStatus||"CREATED"} → ${h.toStatus}`,detail:h.note||"No transition note recorded",actorId:h.actorUserId});
 for(const n of reviewNotes||[])if(n.noteType==="DECISION")events.push({key:`decision-${n.id}`,at:n.createdAt,type:"DECISION",title:`Recommendation: ${(n.recommendation||"UNSPECIFIED").replaceAll("_"," ")}`,detail:n.noteText,actorId:n.reviewerId});
 return events.sort((a,b)=>new Date(a.at||0).getTime()-new Date(b.at||0).getTime());
}
function buildAdmissionDocumentTimeline(documents:any[]){
 const byId=new Map(documents.map(d=>[d.id,d]));
 const depth=(doc:any)=>{let n=1,cur=doc,seen=new Set([doc.id]);while(cur?.replacesDocumentId&&byId.has(cur.replacesDocumentId)&&!seen.has(cur.replacesDocumentId)){seen.add(cur.replacesDocumentId);n++;cur=byId.get(cur.replacesDocumentId);}return n;};
 const events:any[]=[];
 for(const d of documents){const version=depth(d),label=`${d.documentType} · v${version}`;
 events.push({key:`upload-${d.id}`,at:d.createdAt,title:`${label} uploaded`,detail:`${d.displayName} · ${d.status||"PENDING"}`,kind:"upload"});
 if(d.scanRequestedAt)events.push({key:`scan-${d.id}`,at:d.scanRequestedAt,title:`${label} scan requested`,detail:`Security state: ${d.securityStatus||"unknown"}`,kind:"scan"});
 if(d.securityStatus&&d.securityStatus!=="PENDING_UPLOAD")events.push({key:`security-${d.id}`,at:null,title:`${label} current security state`,detail:`Current state: ${d.securityStatus} (state-change timestamp is not retained by this record)`,kind:"security"});
 if(d.reviewedAt)events.push({key:`review-${d.id}`,at:d.reviewedAt,title:`${label} reviewed`,detail:`${d.status} · ${d.reviewNotes||"No reviewer comment recorded"}`,kind:"review"});
 if(d.replacesDocumentId){const parent=byId.get(d.replacesDocumentId);events.push({key:`replace-${d.id}`,at:d.createdAt,title:`${label} replaces previous version`,detail:parent?`${parent.displayName} · prior status ${parent.status}`:`Prior document ID: ${d.replacesDocumentId}`,kind:"replace"});}
 }
 return events.sort((a,b)=>new Date(a.at||0).getTime()-new Date(b.at||0).getTime());
}
